from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel

app = FastAPI()


class ItemCreate(BaseModel):
    name: str


class DuplicateItem(Exception):
    def __init__(self, name: str) -> None:
        self.name = name


@app.exception_handler(DuplicateItem)
def duplicate_item_handler(request: Request, exception: DuplicateItem) -> JSONResponse:
    return JSONResponse(
        status_code=409,
        content={"code": "item_exists", "name": exception.name},
    )


@app.post("/items")
def create_item(payload: ItemCreate) -> dict[str, str]:
    raise DuplicateItem(payload.name)
